class Solution {
    int dp[100][100][101];
    vector<int> b;
    int solve(int i, int j, int k) {
        if (i > j) return 0;
        if (dp[i][j][k] != -1) return dp[i][j][k];
        int res = (k + 1) * (k + 1) + solve(i + 1, j, 0);
        for (int m = i + 1; m <= j; m++) {
            if (b[m] == b[i]) {
                res = max(res, solve(i + 1, m - 1, 0) + solve(m, j, k + 1));
            }
        }
        return dp[i][j][k] = res;
    }
public:
    int removeBoxes(vector<int>& boxes) {
        int n = boxes.size();
        b = boxes;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                for (int k = 0; k <= n; k++)
                    dp[i][j][k] = -1;
        return solve(0, n - 1, 0);
    }
};
